            dfdx(3, 6) = 1;

            dfdx(4, :) = derivatives_drone_IB_syms.df4dx(model, state, ref);
            dfdx(5, :) = derivatives_drone_IB_syms.df5dx(model, state, ref);
            dfdx(6, :) = derivatives_drone_IB_syms.df6dx(model, state, ref);

            dfdx(7, 10) = 1;
            dfdx(8, 11) = 1;
            dfdx(9, 12) = 1;

