        function df12dp = df12dp(model, state, ref)
            df12dp = zeros(1, model.numParams);

            c5 = model.c5;
            lambda3 = model.lambda3;
            refpsi = ref.psi; 
            refpsidot = ref.psi_dot;

            x9 = state(9);
            x12 = state(12);
            x15 = state(15); 

            df12dp(5) = 2*refpsidot - 2*x12 + lambda3*x15 + 2*c5*(refpsi - x9);
            df12dp(15) = refpsi - x9 + c5*x15;
        end
        
